const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {spawnSync} = require('node:child_process');
const test = require('node:test');
const root = path.resolve(__dirname, '..');
const read = name => fs.readFileSync(path.join(root, name), 'utf8');

// AI: below section was generated by an AI
const between = (source, start, end) => {
  const a = source.indexOf(start), b = source.indexOf(end, a);
  assert.ok(a >= 0 && b > a, `missing production block: ${start}`);
  return source.slice(a, b);
};
test('actual notification dispatch selects LAN or ESP-NOW while preserving sender admission and other UDP traffic', async t => {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'castletek-notification-'));
  try {
    const udp = read('wled00/udp.cpp');
    // Use both complete production transport functions. Only lighting parsing,
    // platform/network dependencies and already-admitted ESP RX are faked.
    const source = read('test/fixtures/castletek-notification-host.h') + '\n' +
      between(udp, '#define UDP_SEG_SIZE', 'void notify(') + '\n' +
      between(udp, 'void notify(', 'static void parseNotifyPacket(') + '\n' +
      between(udp, 'void handleNotifications()', '\nvoid setRealtimePixel(') + '\n' +
      read('test/fixtures/castletek-notification-host.cpp');
    const sourcePath = path.join(temporary, 'notification.cpp');
    fs.writeFileSync(sourcePath, source);
    for (const mode of ['compat', 'stock', 'compat-no-espnow']) {
      const binary = path.join(temporary, mode);
      // Existing upstream dispatch uses VLAs. Inactive platform fakes are shared
      // across the compile variants and intentionally unused in some variants.
      const args = ['-std=c++17', '-Wall', '-Wextra', '-Werror', '-Wno-unused-parameter', '-Wno-unused-function', '-Wno-unused-variable', '-Wno-vla', '-I', path.join(root, 'wled00')];
      if (mode !== 'stock') args.push('-DCASTLETEK_WLED_COMPAT');
      if (mode === 'compat-no-espnow') args.push('-DWLED_DISABLE_ESPNOW');
      const compiled = spawnSync(process.env.CXX || 'c++', [...args, sourcePath, '-o', binary], {encoding:'utf8', timeout:60000});
      assert.equal(compiled.status, 0, compiled.stderr || String(compiled.error));
      for (const scenario of ['notify', 'lan', 'lan-envelope', 'esp', 'realtime', 'discovery', 'retries']) {
        await t.test(`${mode}/${scenario}`, () => {
          const ran = spawnSync(binary, [scenario], {encoding:'utf8', timeout:10000});
          assert.equal(ran.status, 0, ran.stderr || String(ran.error));
          assert.match(ran.stdout, /CastleTek notification checks passed: \d+/);
          process.stdout.write(ran.stdout);
        });
      }
    }
  } finally {
    fs.rmSync(temporary, {recursive:true, force:true});
  }
});
// AI: end
